local M=require('jokerless_opening')
local options=SEARCH_REQUEST
assert(type(options.total_limit)=='number' and options.total_limit>=1 and options.total_limit<=6000000 and options.total_limit%1==0)
assert(type(options.batch_limit)=='number' and options.batch_limit>=1 and options.batch_limit<=1000000 and options.batch_limit%1==0)
assert(type(options.max_matches)=='number' and options.max_matches>=1 and options.max_matches<=3 and options.max_matches%1==0)
local result={schema=1,mode=M.mode,status='not_found',start=options.start,limit=options.total_limit,tested=0,next_index=options.start,matches={},batches={},qualification=false}
while result.tested<options.total_limit and #result.matches<options.max_matches do
 local batch={start=result.next_index,limit=math.min(options.batch_limit,options.total_limit-result.tested),max_matches=options.max_matches-#result.matches,
  min_blue=options.min_blue,min_steel=options.min_steel,require_saturn=options.require_saturn,require_telescope=options.require_telescope}
 local current=assert(M.search(catalog,batch))
 assert(current.next_index==batch.start+current.tested and current.tested<=batch.limit)
 assert(current.status=='found' or current.status=='not_found')
 result.tested=result.tested+current.tested;result.next_index=current.next_index
 for _,match in ipairs(current.matches) do result.matches[#result.matches+1]=match end
 result.batches[#result.batches+1]={start=batch.start,limit=batch.limit,tested=current.tested,next_index=current.next_index,matches=#current.matches,status=current.status}
 -- Completed batches and any candidates survive a later timeout as explicit partial evidence.
 print(json({type='completed_search_batch',batch=result.batches[#result.batches],tested=result.tested,next_index=result.next_index,matches=current.matches,qualification=false}));io.stdout:flush()
end
if #result.matches>=options.max_matches then result.status='found' end
PROBE_RESULT_JSON=json(result)
